excels.excel:

EXPORT WITH SHEET="生产计划达成率表", HEADER=true,
    MAPPING={"a":"工单号","b":"产品名称","c":"计划数量","d":"实际产量","e":"达成率","f":"计划完成日","g":"实际完成日","h":"达成状态"},
    FORMAT={"c":"#,##0","d":"#,##0","e":"0.00%","f":"yyyy-MM-dd","g":"yyyy-MM-dd"},
    FORMULAS={
        E2:'D2/C2',E3:'D3/C3',E4:'D4/C4',E5:'D5/C5',E6:'D6/C6',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'AVERAGE(E2:E6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E3:{color:red,bold:true},
        E6:{color:red,bold:true}
    }
